// either: `store.get(idx)` (OVH-003 -- `List<T>.get()`/`.set()`, the
// bounds-checked generic replacement for reading/writing an element via
// the raw `data: T*` field directly) yields an `Entry` by value, so
// `.key`/`.value` field access on it is ordinary struct field access, not
// a dereference through a raw `Entry*` base.

import io;
import net;
import strings;
import list::List;

struct Entry {
    key: string,
    value: string
}

// List<T>'s own `get(i)` (OVH-003) gives direct indexed access --
// List.push()/pop()/length() alone would only support stack-shaped access,
// not the "find by key" scan a KV store actually needs. There's no
// Map<K,V> in the standard library yet (see
// docs/planning/STDLIB_ROADMAP.md) -- this linear scan is the honest
// current alternative for a small store like this one.
fn find_index(store: List<Entry>, key: string): int {
    mut i: int = 0;
    while i < store.length() {
        if store.get(i).key == key {
            return i;
        }
        i = i + 1;
    }
    return -1;
}

fn main(): int {
    mut store: List<Entry> = List<Entry>::default();
    mut server: net::TcpListener = net::TcpListener.bind(8181) recover run {
        io::printline("Could not start the store -- is port 8181 already in use?");
        return 1;
    };
    defer server.close();
    io::printline("Turf key-value store listening on port 8181...");

    mut request_count: int = 0;
    while request_count < 1000 {
        // A single bad accept() shouldn't bring the whole store down --
        // log it and keep serving instead of aborting.
        mut conn: net::TcpConnection = server.accept() recover run {
            io::printline("accept() failed, skipping.");
            continue;
        };
        // Runs at the end of THIS iteration on every path out of it.
        defer conn.close();
        immut line: string = strings::trim(conn.read(4096));

        immut first_space: int = strings::index_of(line, " ");
        if first_space < 0 {
            conn.write("ERROR malformed command\n");
        } else {
            immut cmd: string = strings::substring(line, 0, first_space);
            immut rest: string = strings::substring(line, first_space + 1, strings::length(line));

            if cmd == "GET" {
                immut idx: int = find_index(store, rest);
                if idx >= 0 {
                    conn.write(store.get(idx).value + "\n");
                } else {
                    conn.write("NOT_FOUND\n");
                }
            } elseif cmd == "SET" {
                immut second_space: int = strings::index_of(rest, " ");
                if second_space < 0 {
                    conn.write("ERROR: SET needs a key and a value\n");
                } else {
                    immut key: string = strings::substring(rest, 0, second_space);
                    immut value: string = strings::substring(rest, second_space + 1, strings::length(rest));
                    immut idx: int = find_index(store, key);
                    if idx >= 0 {
                        // A read-modify-write, not a through-pointer field
                        // write: List.get() returns Entry BY VALUE (OVH-003
                        // -- there's no `.data[idx].value = ...` any more to
                        // write through in the first place), so the mutated
                        // copy has to go back in via List.set().
                        mut e: Entry = store.get(idx);
                        e.value = value;
                        store.set(idx, e);
                    } else {
                        mut e: Entry = Entry::default();
                        e.key = key;
                        e.value = value;
                        store.push(e);
                    }
                    conn.write("OK\n");
                }
            } else {
                conn.write("ERROR: unknown command '" + cmd + "'\n");
            }
        }

        request_count = request_count + 1;
    }

    io::printline("Handled 1000 requests, shutting down.");
    return 0;
}

// A tiny in-memory key-value store, served over TCP -- a miniature
// Redis-shaped service written entirely in Turf. Combines three separate
// stdlib pieces (net, list, strings) the way a real small service would:
// state held in a generic collection, a hand-rolled text protocol parsed
// with string primitives, network I/O via the net module. No `extern fn`
// anywhere in this file.
//
// Protocol: one command per connection (connect, send one line, get one
// line back, connection closes) -- kept simple deliberately; see
// showcase/http_server.tr for the same "process an accepted connection"
// shape applied to HTTP instead.
//   SET <key> <value>   -> "OK"
//   GET <key>           -> the value, or "NOT_FOUND"
