// A standard library failure carries a message saying what failed, besides
// its payload. Every one was built with no message, so a handler printing
// `err.message` printed a blank line.

import test;
import fs;
import json;
import map::Map;

fn fs_message(): string {
    mut m: string = "";
    fs::mkdir("/nonexistent_turf_dir/sub") recover as err run { m = err.message; };
    return m;
}

fn io_message(): string {
    immut s: string = io::read_to_string("/nonexistent_turf_dir/f.txt") recover as err run {
        return err.message;
    };
    return "read " + s;
}

fn parse_message(): string {
    immut n: int = strings::parse_int("x1") recover as err run { return err.message; };
    return n to string;
}

fn divide_message(): string {
    immut q: int = math::divide(1, 0) recover as err run { return err.message; };
    return q to string;
}

fn map_message(): string {
    mut m: Map<string, int> = Map{};
    immut v: int = m.try_get("k") recover as err run { return err.message; };
    return v to string;
}

fn json_message(): string {
    immut j: json::JsonValue = json::parse("[1,") recover as err run { return err.message; };
    return typeof(j);
}

fn main(): int {
    test::assert(fs_message() == "could not create directory '/nonexistent_turf_dir/sub'", "fs");
    test::assert(io_message() == "file not found: '/nonexistent_turf_dir/f.txt'", "io");
    test::assert(parse_message() == "not an int: 'x1'", "strings");
    test::assert(divide_message() == "division by zero", "math");
    test::assert(map_message() == "key not found", "map");
    test::assert(json_message() == "unexpected end of JSON at offset 3", "json");
    return 0;

// Regression test: lib/std/collections/set.tr (Set<T>), imported and
// exercised end-to-end -- add/contains/remove/length, duplicate-add being
// a no-op, and growth past the initial capacity.
import set::Set;
import test;

fn main(): int {
    mut s: Set<int> = Set::default();
    test::assert(s.length() == 0, "new set starts empty");

    s.add(1);
    s.add(2);
    s.add(3);
    test::assert(s.length() == 3, "three distinct adds should give length 3");
    test::assert(s.contains(1) == true, "");
    test::assert(s.contains(2) == true, "");
    test::assert(s.contains(3) == true, "");
    test::assert(s.contains(4) == false, "not-added item should not be contained");

    // Duplicate add must be a no-op (no length change, no growth).
    s.add(2);
    test::assert(s.length() == 3, "adding an already-present item must be a no-op");

    // remove() reports whether it actually removed something.
    immutable removedExisting: bool = s.remove(2);
    test::assert(removedExisting == true, "removing a present item returns true");
    test::assert(s.length() == 2, "length drops after a real removal");
    test::assert(s.contains(2) == false, "removed item is no longer contained");

    immutable removedMissing: bool = s.remove(999);
    test::assert(removedMissing == false, "removing an absent item returns false");
    test::assert(s.length() == 2, "removing an absent item must not change length");

    // Force growth past the initial capacity (8).
    mut big: Set<int> = Set::default();
    mut i: double = 0;
    while i < 20 {
        big.add(i);
        i = i + 1;
    }
    test::assert(big.length() == 20, "20 distinct adds should give length 20");
    // Re-adding everything again must not grow the set further.
    i = 0;
    while i < 20 {
        big.add(i);
        i = i + 1;
    }
    test::assert(big.length() == 20, "re-adding existing items must not change length");

    return 0;
}

// Regression test (OVH-003, docs/planning/OVERHAUL_REMAINING_WORK.md):
// `List<T>.get(i)`/`.set(i, value)` -- the bounds-checked, GENUINELY
// generic replacement for reading/writing an element via the raw `data:
// T*` field directly (`l.data[i]`, now gated outside `unsafe { }` -- see
// tests/05_arrays_pointers_ffi/rejected_in_functions.tr: rejects_raw_pointer_index_outside_unsafe).
// Unlike `operator[]`/`operator[]=` (LANG-001), which are declared for
// the concrete `List<int>` only, `get`/`set` work for any `T` -- covered
// here across a primitive (`int`), a GC-heap pointer type (`string`), and
// a genuine multi-field by-value struct (`Triple`, 24 bytes -- three
// int64 fields, exercising the >8-byte-struct-by-value path TYPE-002
// made possible).

import list::List;
import test;

struct Triple {
    a: int,
    b: int,
    int c;
}

fn main(): int {
    // int
    mut li: List<int> = List::default();
    li.push(10);
    li.push(20);
    li.push(30);
    test::assert(li.get(0) == 10 && li.get(1) == 20 && li.get(2) == 30,
        "List<int>.get reads pushed values");
    li.set(1, 99);
    test::assert(li.get(1) == 99, "List<int>.set overwrites in place");

    // string (a GC-heap pointer element type)
    mut ls: List<string> = List::default();
    ls.push("alpha");
    ls.push("beta");
    test::assert(ls.get(0) == "alpha" && ls.get(1) == "beta",
        "List<string>.get reads pushed values");
    ls.set(0, "gamma");
    test::assert(ls.get(0) == "gamma", "List<string>.set overwrites in place");

    // a genuine multi-field by-value struct, 24 bytes
    mut lt: List<Triple> = List::default();
    mut t1: Triple = Triple::default();
    t1.a = 1; t1.b = 2; t1.c = 3;
    lt.push(t1);
    test::assert(lt.get(0).a == 1 && lt.get(0).b == 2 && lt.get(0).c == 3,
        "List<Triple>.get reads all three fields correctly");
    mut t2: Triple = Triple::default();
    t2.a = 7; t2.b = 8; t2.c = 9;
    lt.set(0, t2);
    test::assert(lt.get(0).a == 7 && lt.get(0).b == 8 && lt.get(0).c == 9,
        "List<Triple>.set overwrites the whole struct in place");

    return 0;
}

// A Map and a Set under steady churn: a sliding window of keys, each step one
// insert and one remove, so the size stays put while tens of thousands of
// entries come and go. Tombstones now count toward the rebuild check, and a
// rebuild at the same size clears them. Before, they filled every empty slot
// and every lookup of a missing key probed the whole table (found by REL-005's
// benchmarks; the cost grew with the table). This checks the answers stay
// right through those rebuilds; bench/map_churn.tr tracks the speed.

import test;
import map::Map;
import set::Set;

fn main(): int {
    immut window: int = 300;
    immut steps: int = 30000;
    mut m: Map<int, int> = Map::default();
    mut s: Set<int> = Set::default();
    for i in 0..steps {
        m.put(i, i * 2);
        s.add(i);
        if (i >= window) {
            m.remove(i - window);
            test::assert(s.remove(i - window), "the set held the key leaving the window");
            test::assert(!m.contains(i - window), "a removed key is gone");
            test::assert(m.get(i - window + 1) == (i - window + 1) * 2, "the oldest live key is found");
            test::assert(s.contains(i), "the newest set key is found");
        }
        test::assert(m.length() == s.length(), "map and set agree on size");
    }
    test::assert(m.length() == window, "the map holds exactly the window");
    mut sum: int = 0;
    for k in range((steps - window), steps) {
        sum = sum + m.get(k);
    }
    test::assert(sum == window * (2 * steps - window - 1), "every live key maps to its value");
    test::assert(!s.contains(steps - window - 1), "nothing older survived");
    return 0;
}

// A JSON number may have an exponent (RFC 8259: `1e10`, `2.5E-3`,
// `-1.5e+2`), and json::stringify writes one for a large or small number
// (`%g`: 1e+21, 1e-06). json::parse failed on every such number, so a value
// json::stringify wrote could not be read back: strings::parse_double
// rejected exponents (the header claimed only the value came out wrong).

import json;
import test;

// A `return` inside `recover run` returns from the enclosing function, so the
// failure check lives in its own helper.
fn rejects(text: string): bool {
    immut v: json::JsonValue = json::parse(text) recover run {
        return true;
    };
    return v.length() < 0;
}

fn main(): int {
    immut v: json::JsonValue = json::parse("[3e2, -1.5E-3, 1e+21, 2, 0.5e1]") recover run {
        test::fail("numbers with exponents are valid JSON");
        return 1;
    };
    test::assert_eq(v.length(), 5, "five numbers");
    test::assert_eq(v.at(0).num_val, 300.0, "3e2");
    test::assert_eq(v.at(1).num_val, -0.0015, "-1.5E-3");
    test::assert_eq(v.at(2).num_val, 1e21, "1e+21");
    test::assert_eq(v.at(4).num_val, 5.0, "0.5e1");

    // What stringify writes with an exponent reads back.
    mut arr: json::JsonValue = json::JsonValue.new_array();
    arr.push(json::JsonValue::from_number(1e21));
    arr.push(json::JsonValue::from_number(0.000001));
    immut text: string = json::stringify(arr);
    test::assert_eq(text, "[1e+21,1e-06]", "stringify uses an exponent");
    immut back: json::JsonValue = json::parse(text) recover run {
        test::fail("a stringified document parses back");
        return 1;
    };
    test::assert_eq(back.at(0).num_val, 1e21, "1e+21 round trip");
    test::assert_eq(back.at(1).num_val, 0.000001, "1e-06 round trip");

    // An exponent with no digits is still malformed.
    test::assert(rejects("[1e]"), "'1e' is rejected");
    test::assert(rejects("[1e+]"), "'1e+' is rejected");
    test::assert(!rejects("[1E5]"), "'1E5' is accepted");
    return 0;
}

// SEM-002: regression coverage for docs/reference/variables_and_types.md's
// "Legal conversions" table -- confirms the existing Codegen truncation/
// conversion behavior for every numeric `to`-cast pair is unchanged now
// that cast LEGALITY is checked earlier, in the TypeChecker (Rule B1),
// instead of only in Codegen. See TypeChecker::visitCast()'s own comment
// (TypeCheckerExpr.cpp) for the moved check itself.

