// Regression test: an explicit `to`-cast involving a generic type
// parameter used to be rejected UNCONDITIONALLY at the TEMPLATE's own
// definition site, regardless of whether any real instantiation would
// have made the cast legal -- src/sema/TypeCheckerExpr.cpp's `visitCast()` cast-
// legality whitelist had no bypass for `TurfGenericParamType`, unlike
// every other type-checking path in this compiler (equality, argument
// matching), which all defer the real check to a per-instantiation
// clone's own re-typecheck. Found live while investigating whether
// `mem::Pool<T>` could gain a genuine generic `free_all()` method
// (docs/development/changes/STD-003.md) -- a cast from a generic
// parameter failed to compile even where the only real caller
// instantiates a type the cast is already legal for.
import test;

// The minimal repro: a cast from a plain generic PARAMETER (not a field
// access -- see this test's own final note below for why that distinction
// matters) to a concrete type, inside a generic function -- used to fail
// at THIS declaration regardless of whether castToInt() is ever called.
fn<T> castToInt(x: T): int {
    return x to int;
}

// SMP-002 (2026-09-27): the field-access case this file used to document
// as a known, deferred gap (see the removed trailing note this comment
// replaces) is verified fixed -- `self.v`'s type resolves through
// GlobalSymbolTable's own registered TurfStructType for the struct, which
// OVH-006 (landed 2026-09-26, before this test was re-checked) made carry
// the real TurfGenericParamType("T") instead of a permanently-stale
// NamedType("T"). `visitCast()`'s own generic-parameter bypass (now
// TypeWalk::containsOpenParam(..., ParamScope::Bare), TypeWalk.h) never
// needed a NamedType fallback of its own once that representation was
// fixed at the source.
struct Box<T> {
    v: T
}

fn<T> Box.castToInt(): int {
    return self.v to int;
}

fn main(): int {
    test::assert(castToInt(42) == 42, "cast from a genuinely-int-instantiated T works");

    // A DIFFERENT instantiation, to prove the fix isn't int-specific -- int32
    // is the only OTHER primitive type this same cast (`to int`) is legal
    // for, per the existing whitelist (`int32 -> int`).
    immutable thirtyTwo: int32 = 7 to int32;
    test::assert(castToInt(thirtyTwo) == 7, "cast from a genuinely-int32-instantiated T works too");

    mut b: Box<int> = Box::default();
    b.v = 99;
    test::assert(b->castToInt() == 99, "self.v to int (field access, not a bare parameter) also works");

    return 0;
}

// A `defer` runs when its block exits, after a `return` has computed its
// value: `return p` here returns the heap node, and the deferred `p = &n`
// only changes a variable that is about to die. It was a false E086 while
// the defer counted where it is written (owner decision 2026-10-12, found
// by turf-fuzz). See fail_escape_defer_* for the paths that do escape.

import test;

struct N { val: int, next: &?N }

fn f(): &N {
    mut n: N = N::default();
    n.val = 42;
    mut p: &N = heap(n);
    defer p = &n;
    return p;
}

fn g(c: bool): &N {
    mut n: N = N::default();
    n.val = 7;
    mut p: &N = heap(n);
    if (c) {
        defer p = &n;
        return p;
    }
    return p;
}

fn main(): int {
    test::assert(f().val == 42, "returned before the defer ran");
    test::assert(g(true).val == 7, "defer in a branch that returns")
    test::assert(g(false).val == 7, "defer in a branch not taken");
    return 0;
}

// A payload may carry a reference the function was given, or a heap one:
// both outlive the frame (contrast fail_escape_error_payload.tr).

import test;

struct N { val: int, next: &?N }

error E1 {
    P(r: &N),
    Q
}

fn fail_with(p: &N): !int {
    return E1::P(p);
}

fn fail_with_heap(): !int {
    mut n: N = N::default();
    n.val = 9;
    return E1::P(heap(n));
}

fn payload_val(fail_heap: bool, p: &N): int {
    mut v: int = fail_with_heap() if (fail_heap else fail_with(p)) recover as err run {
        compare err {
            matches E1::P(r):
            return r.val;
            done
            otherwise:
            return -1;
        }
    };
    return v;
}

fn main(): int {
    mut n: N = N::default();
    n.val = 42;
    test::assert(payload_val(false, &n) == 42, "payload reference to the caller's object");
    test::assert(payload_val(true, &n) == 9, "payload reference to a heap object");
    return 0;
}

// A reference that is `&n` on one path and the heap on another is fine as
// long as it never reaches a sink: only an escape on some path is E086
