struct Box { n: int }

fn pick(int v): int {
    mut b: Box = Box::default();
    b.n = v;
    mut r: int;
    compare b {
        matches Box { n } if n > 100:
        r = 1;
        done
        matches Box { n } if n > 10:
        r = 2;
        done
        matches Box { .. }:
        r = 3;
        done
    }
    return r;
